import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Flex, Typography } from 'antd';

import ErrorIcon from 'assets/images/status/error.svg?react';
import ModerationIcon from 'assets/images/status/moderation.svg?react';
import SuccessIcon from 'assets/images/status/success.svg?react';
import { ESourceRelationStatuses, ISourceRelation } from 'entities/Offer';
import { useMedia } from 'shared/hooks';
import { getNoun } from 'shared/utils';

interface IJoinedStatusProps extends HTMLAttributes<HTMLDivElement> {
	sourceRelations: ISourceRelation[];
	isDashboard?: boolean;
}

export const JoinedStatus: FC<IJoinedStatusProps> = ({ sourceRelations, isDashboard, ...props }) => {
	const { t } = useTranslation();
	const isMd = useMedia();
	const isSmall = isMd || isDashboard;

	const sources = sourceRelations.filter(({ status }) => status !== ESourceRelationStatuses.DISABLED);

	let status: ESourceRelationStatuses | null = null;

	const joinedSources = sources.filter(({ status }) => status === ESourceRelationStatuses.JOINED);
	const moderationSources = sources.filter(({ status }) => status === ESourceRelationStatuses.VERIFICATION);
	const rejectedSources = sources.filter(({ status }) => status === ESourceRelationStatuses.REJECTED);

	if (joinedSources.length > 0) {
		status = ESourceRelationStatuses.JOINED;
	} else if (moderationSources.length > 0) {
		status = ESourceRelationStatuses.VERIFICATION;
	} else if (rejectedSources.length > 0) {
		status = ESourceRelationStatuses.REJECTED;
	}

	if (!status) return null;

	const statusMap = {
		[ESourceRelationStatuses.JOINED]: {
			icon: <SuccessIcon />,
			text: t('Подключены'),
			count: joinedSources.length,
		},
		[ESourceRelationStatuses.VERIFICATION]: {
			icon: <ModerationIcon />,
			text: t('На модерации'),
			count: moderationSources.length,
		},
		[ESourceRelationStatuses.REJECTED]: {
			icon: <ErrorIcon />,
			text: t('Отклонены'),
			count: rejectedSources.length,
		},
	};

	return (
		<Flex vertical={!isSmall} align="end" gap={4} {...props}>
			<Flex align="center" gap={4} {...props}>
				{statusMap[status].icon}
				<Typography.Text type="secondary">{statusMap[status].text}: </Typography.Text>
			</Flex>

			<Typography.Text strong style={{ whiteSpace: 'nowrap' }}>
				{statusMap[status].count} {t('из')} {sources.length}{' '}
				{getNoun(sources.length, ['площадки', 'площадок', 'площадок'])}
			</Typography.Text>
		</Flex>
	);
};
