import { FC, HTMLAttributes } from 'react';

import { Flex, theme } from 'antd';
import cn from 'classnames';

import AngleIcon from 'assets/images/icons/angle-right.svg?react';

import styles from './BrandAccordion.module.scss';

interface IBrandAccordionProps extends HTMLAttributes<HTMLDivElement> {
	isOpen: boolean;
	setIsOpen: (isOpen: boolean) => void;
	buttonText: string;
}

export const BrandAccordion: FC<IBrandAccordionProps> = ({ children, isOpen, setIsOpen, buttonText }) => {
	const {
		token: { colorBorderSecondary, colorBgLayout },
	} = theme.useToken();

	return (
		<>
			<button className={styles.collapse} style={{ backgroundColor: colorBgLayout }} onClick={() => setIsOpen(!isOpen)}>
				{buttonText}
				<AngleIcon className={cn(styles.angle, { [styles.opened]: isOpen })} />
			</button>

			{isOpen && (
				<Flex
					vertical
					gap={8}
					className={styles.list}
					style={{ borderColor: colorBorderSecondary, backgroundColor: colorBgLayout }}>
					{children}
				</Flex>
			)}
		</>
	);
};
