import { FC } from 'react';

import { Flex, FlexProps, theme, Typography } from 'antd';
import cn from 'classnames';

import styles from './Parameter.module.scss';

interface IParameterProps extends FlexProps {
	label: string;
	isLast?: boolean;
	isDashboard?: boolean;
}

export const Parameter: FC<IParameterProps> = ({ className, children, label, isLast, isDashboard, ...props }) => {
	const {
		token: { colorBorderSecondary },
	} = theme.useToken();

	return (
		<Flex
			{...props}
			className={cn(className, styles.parameter, { [styles.last]: isLast, [styles.dashboard]: isDashboard })}
			style={{ borderColor: colorBorderSecondary }}>
			<Typography.Text type="secondary" className={styles.label}>
				{label}
			</Typography.Text>
			<Typography.Text strong className={styles.value}>
				{children}
			</Typography.Text>
		</Flex>
	);
};
