import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Card, Flex, theme, Typography } from 'antd';
import cn from 'classnames';

import { ISourceRelation } from 'entities/Offer';
import { JoinedSourceLinks, SourceStatus } from 'entities/Source';
import { useMedia } from 'shared/hooks';

import styles from './JoinedSourceCard.module.scss';

const { Text } = Typography;

interface IJoinedSourceCardProps extends HTMLAttributes<HTMLDivElement> {
	sourceRelation: ISourceRelation;
	offer: string;
}

export const JoinedSourceCard: FC<IJoinedSourceCardProps> = ({ className, sourceRelation, offer, ...props }) => {
	const { t } = useTranslation();
	const isMd = useMedia();
	const {
		token: { colorBorderSecondary },
	} = theme.useToken();
	const { status, rejection_comment, affiliate_links, source } = sourceRelation;

	return (
		<Card styles={{ body: { padding: 0 } }}>
			<div {...props} className={cn(className, styles.card)}>
				<div className={styles.title} style={{ borderColor: colorBorderSecondary }}>
					<Text strong>{source.name}</Text>
				</div>

				<Flex vertical gap={8} className={styles.item}>
					{isMd && (
						<Text type="secondary" style={{ fontSize: 12 }}>
							{t('Статус')}
						</Text>
					)}
					<SourceStatus sourceStatus={status} />
				</Flex>

				<Flex vertical gap={8} className={styles.item}>
					{isMd && (
						<Text type="secondary" style={{ fontSize: 12 }}>
							{affiliate_links?.length ? t('Ссылка') : t('Комментарий')}
						</Text>
					)}
					{affiliate_links?.length ? (
						<span>
							<JoinedSourceLinks sourceUuid={source.uuid} offerUuid={offer} count={affiliate_links.length} />
						</span>
					) : (
						<Text>{rejection_comment || '-'}</Text>
					)}
				</Flex>
			</div>
		</Card>
	);
};
