import { FC, HTMLAttributes, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, Card, Flex, theme, Tooltip } from 'antd';
import cn from 'classnames';

import { IBrand, useBrandsSlice } from 'entities/Brand';
import { IOffer, JoinedStatus, OfferTitle } from 'entities/Offer';
import { useJoinOffer } from 'entities/Offer/hooks/useJoinOffer';
import { JoinedSourceCard } from 'entities/Source';
import { useMedia, useMeta } from 'shared/hooks';
import { BrandAccordion, Parameter } from 'shared/ui';
import { getNoun } from 'shared/utils';

import styles from './OfferCard.module.scss';

interface IOfferCardProps extends HTMLAttributes<HTMLDivElement> {
	offer: IOffer;
	brand?: IBrand;
	allIsOpened?: boolean;
	isMyOffers?: boolean;
	isDashboard?: boolean;
	isBests?: boolean;
}

export const OfferCard: FC<IOfferCardProps> = ({
	className,
	offer,
	brand,
	allIsOpened,
	isMyOffers,
	isDashboard,
	isBests,
	...props
}) => {
	const { t } = useTranslation();
	const {
		token: { colorBorderSecondary },
	} = theme.useToken();
	const isMd = useMedia();
	const isSmall = isMd || isDashboard;
	const { setOpenedOffer } = useBrandsSlice();
	const [isOpen, setIsOpen] = useState(!!allIsOpened);

	const { brandsMap } = useMeta();
	const fullBrand = brandsMap?.[offer?.brand?.uuid as keyof typeof brandsMap];
	const { joinIsDisabled, onJoin } = useJoinOffer(fullBrand, offer);

	useEffect(() => {
		setIsOpen(!!allIsOpened);
	}, [allIsOpened]);

	return (
		<Card
			{...props}
			className={cn(className, styles.card, { [styles.dashboard]: isDashboard })}
			styles={{ body: { padding: 0, height: isDashboard ? '100%' : 'auto' } }}>
			<Flex vertical gap={16} className={styles.main}>
				<Flex gap={isSmall ? 12 : 16} className={styles.header} style={{ borderColor: colorBorderSecondary }}>
					<OfferTitle offer={offer} isMyOffers={isMyOffers} isDashboard={isDashboard} />
					{(!isDashboard || isBests) && (
						<JoinedStatus sourceRelations={offer.sources_relations} isDashboard={isDashboard} />
					)}
				</Flex>

				<Flex className={styles.parameters}>
					<Parameter label={t('Ставка')} isDashboard={isDashboard}>
						<Flex vertical>
							{offer.grouped_rates.percent_payout_sizes && <span>{offer.grouped_rates.percent_payout_sizes}</span>}
							{offer.grouped_rates.fixed_payout_size && <span>{offer.grouped_rates.fixed_payout_size}</span>}
						</Flex>
					</Parameter>

					<Parameter label={t('EPC')} isDashboard={isDashboard}>
						{offer.epc ? `${t('от')} ${offer.epc} ${offer.currency?.sign}` : '-'}
					</Parameter>

					<Parameter label={t('CR')} isDashboard={isDashboard}>
						{offer.cr ? `${t('от')} ${offer.cr} %` : '-'}
					</Parameter>

					<Parameter label={t('AR')} isDashboard={isDashboard}>
						{offer.ar ? `${t('от')} ${offer.ar} %` : '-'}
					</Parameter>

					{!!offer.landings?.length && (
						<Tooltip
							title={
								<ul className={styles.landingsTooltip}>
									{offer.landings.map(({ name }) => (
										<li key={name}>{name}</li>
									))}
								</ul>
							}>
							<Parameter label={t('Лендинги')} isDashboard={isDashboard}>
								{offer.landings.length}
							</Parameter>
						</Tooltip>
					)}

					<Flex vertical={isSmall} gap={16} className={styles.buttons}>
						<Button
							variant={isSmall ? 'outlined' : 'text'}
							color={isSmall ? 'default' : 'primary'}
							size="small"
							style={{ padding: '0 21px' }}
							onClick={() => setOpenedOffer({ offer, brand: brand || fullBrand })}>
							{t('Подробнее')}
						</Button>
						<Tooltip
							title={
								joinIsDisabled
									? t(
											'Вы подали заявку/заявки на все ваши площадки. Чтобы снова подать заявку вам нужно добавить новую площадку.',
										)
									: undefined
							}>
							<Button
								type="primary"
								size="small"
								onClick={() => onJoin()}
								style={{ padding: '0 21px' }}
								disabled={joinIsDisabled}>
								{t('Подключиться')}
							</Button>
						</Tooltip>
					</Flex>
				</Flex>
			</Flex>

			{isMyOffers && (
				<BrandAccordion
					isOpen={isOpen}
					setIsOpen={setIsOpen}
					buttonText={`${t('Показать {{count}} ', { count: offer.sources_relations.length })} ${getNoun(offer.sources_relations.length, [t('площадку'), t('площадки'), t('площадок')])}`}>
					{offer.sources_relations.map((sourceRelation) => (
						<JoinedSourceCard key={sourceRelation.source.uuid} sourceRelation={sourceRelation} offer={offer.uuid} />
					))}
				</BrandAccordion>
			)}
		</Card>
	);
};
